 const fd=fs.openSync(p,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);
 const first=fs.fstatSync(fd,{bigint:true}), b=fs.readFileSync(fd),last=fs.fstatSync(fd,{bigint:true});fs.closeSync(fd);
 const named=fs.lstatSync(p,{bigint:true});for(const v of [first,last,named])for(const k of ['dev','ino','mode','size','mtimeNs','ctimeNs'])assert.equal(v[k],a[k]);
 assert.equal(BigInt(b.length),a.size); return {body:b,identity:{path:p,bytes:b.length,sha256:hash(b)}};
}
