function walk(v){if(v&&typeof v==='object'){if(typeof v.path==='string'&&Number.isInteger(v.bytes)&&typeof v.sha256==='string'){const p=known.get(v.path);assert(p,'unselected '+v.path);assert.equal(v.bytes,p.bytes);assert.equal(v.sha256,p.sha256);typed++;}for(const x of Object.values(v))walk(x);}}
